{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Integrative Care for Whole-You</title>
  <meta name="description" content="Whole-person integrative medicine focusing on education, personalized plans, and sustainable wellbeing." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body>
  <header class="site-header">
    <div class="container header-inner">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav" id="mainNav" aria-label="Primary navigation">
        <ul>
          <li><a href="/services.html">Services</a></li>
          <li><a href="/conditions.html">Concerns</a></li>
          <li><a href="/approach.html">How We Work</a></li>
          <li><a href="/pricing.html">Rates</a></li>
          <li><a href="/about.html">Our Story</a></li>
          <li><a href="/book.html" class="cta primary">{{PRIMARY_CTA_LABEL}}</a></li>
          <li><a href="/contact.html">Connect</a></li>
        </ul>
      </nav>
      <button id="navToggle" aria-label="Toggle navigation" aria-expanded="false">☰</button>
    </div>
  </header>

  <main>
    <section class="hero">
      <div class="pattern" aria-hidden="true"></div>
      <div class="container hero-inner">
        <h1 class="title">{{TAGLINE}}</h1>
        <p class="subtitle">Personalized integrative care blending evidence-informed strategies and whole-person attention. We focus on education, partnership, and small, sustainable steps — not promises of cures.</p>
        <div class="hero-ctas">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/about.html">Meet {{PRACTITIONER_NAME}}</a>
        </div>
      </div>
    </section>

    <section class="social-proof">
      <div class="container">
        <h2>Voices from the practice</h2>
        <div class="testimonials">
          <blockquote>
            “Compassionate listening and clear next steps — I finally understand what my body needs.”
            <cite>— A local client</cite>
          </blockquote>
          <blockquote>
            “Gentle, practical guidance. The focus on daily habits changed my energy rhythm.”
            <cite>— Member in {{CITY}}</cite>
          </blockquote>
        </div>
      </div>
    </section>

    <section class="benefits">
      <div class="container">
        <h2>Why integrative support helps</h2>
        <ul class="benefit-grid">
          <li>
            <h3>True whole-person care</h3>
            <p>We map lifestyle, environment, and symptom patterns together to form context-rich plans.</p>
          </li>
          <li>
            <h3>Education first</h3>
            <p>Understand why symptoms happen and what simple steps help restore balance.</p>
          </li>
          <li>
            <h3>Tailored plans</h3>
            <p>Recommendations are paced to your readiness and practical routines.</p>
          </li>
          <li>
            <h3>Optional testing</h3>
            <p>Labs are used as educational tools when they add clarity to a care plan.</p>
          </li>
        </ul>
      </div>
    </section>

    <section class="process">
      <div class="container">
        <h2>Our approach: a simple pathway</h2>
        <ol class="process-list">
          <li><strong>Comprehensive intake</strong> — A thoughtful conversation to gather history, lifestyle, and goals.</li>
          <li><strong>Personalized plan</strong> — Practical changes across nutrition, sleep, movement, and stress skills; optional labs discussed openly.</li>
          <li><strong>Follow-ups</strong> — Short check-ins to refine the plan and build skills.</li>
          <li><strong>Ongoing support</strong> — Education and troubleshooting so improvements stick.</li>
        </ol>
      </div>
    </section>

    <section class="faq">
      <div class="container">
        <h2>Frequently asked</h2>
        <dl>
          <dt>Do you guarantee cures?</dt>
          <dd>No. The practice emphasizes education, risk-aware choices, and partnership; individual responses vary.</dd>
          <dt>Are lab tests required?</dt>
          <dd>Labs are optional and considered when they provide useful information to guide care.</dd>
          <dt>Who benefits from this work?</dt>
          <dd>People seeking whole-person support for stress, sleep, digestion, inflammation, or low energy often find practical benefit.</dd>
        </dl>
      </div>
    </section>

    <section class="lead-magnet">
      <div class="container">
        <h2>Free guide — 7 Daily Practices to Rebalance</h2>
        <p>Sign up to receive a concise, practical guide with gentle, evidence-informed steps you can try today.</p>
        <form id="leadForm" class="lead-form" novalidate>
          <input type="email" id="leadEmail" name="email" placeholder="you@email.com" required aria-label="Email address" />
          <button class="btn primary" type="submit">Send my guide</button>
        </form>
        <p class="privacy">We respect your privacy. No spam — unsubscribe any time.</p>
      </div>
    </section>

    <section class="cta-band">
      <div class="container cta-inner">
        <h3>Ready to explore a personalized path?</h3>
        <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-inner">
      <div class="left">
        <p>{{PRACTITIONER_NAME}}, {{CREDENTIALS}} — {{CITY}}, {{STATE}}</p>
        <p>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a> Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <nav class="footer-nav" aria-label="Footer navigation">
        <a href="/services.html">Services</a>
        <a href="/contact.html">Contact</a>
        <a href="/privacy.html">Privacy</a>
      </nav>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
