{"path":"assets/css/styles.css","content":"/* Holistic / mystic-modern aesthetic: gradients, soft glass, and pattern overlay */
:root{--bg:#0f1720;--card:#0b1220;--muted:#9aa5ad;--accent1:#7bd389;--accent2:#7cc6ff;--glass:rgba(255,255,255,0.04);--max-width:1100px}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#ecf8f6;background:linear-gradient(180deg,#07101a 0%,#081722 50%,#041018 100%);-webkit-font-smoothing:antialiased}
.container{width:90%;max-width:var(--max-width);margin:0 auto}
.site-header{position:sticky;top:0;z-index:40;background:linear-gradient(180deg,rgba(6,12,16,0.6),rgba(6,12,16,0.2));backdrop-filter:blur(6px);border-bottom:1px solid rgba(255,255,255,0.02)}
.header-inner{display:flex;align-items:center;justify-content:space-between;padding:0.9rem 0}
.brand{font-weight:700;color:var(--accent2);text-decoration:none;font-size:1.05rem}
.nav ul{display:flex;gap:0.75rem;list-style:none;margin:0;padding:0}
.nav a{color:rgba(255,255,255,0.88);text-decoration:none;padding:0.45rem 0.6rem;border-radius:6px}
.nav a:hover{background:rgba(255,255,255,0.02)}
#navToggle{display:none;background:none;border:0;color:var(--accent2);font-size:1.2rem}
@media(max-width:880px){.nav{display:none;position:absolute;top:64px;right:12px;background:linear-gradient(180deg,rgba(8,12,16,0.98),rgba(6,9,12,0.98));padding:12px;border-radius:10px;box-shadow:0 6px 30px rgba(2,6,10,0.6)}
.nav ul{flex-direction:column}
#navToggle{display:block}}
.hero{position:relative;padding:4rem 0 3rem;overflow:hidden}
.pattern{position:absolute;inset:0;background-image:url('../assets/img/pattern.svg');background-repeat:no-repeat;background-size:cover;opacity:0.18;mix-blend-mode:screen;filter:blur(0.5px)}
.hero-inner{position:relative;padding:3rem 0;color:#ecfcf8}
.title{font-size:clamp(1.6rem,3.6vw,2.6rem);margin:0 0 0.5rem;line-height:1.05;color:linear-gradient(90deg,var(--accent1),var(--accent2))}
.subtitle{color:var(--muted);max-width:70ch}
.hero-ctas{margin-top:1.2rem;display:flex;gap:0.8rem;flex-wrap:wrap}
.btn{display:inline-block;padding:0.65rem 1rem;border-radius:8px;text-decoration:none;font-weight:600;cursor:pointer;border:1px solid transparent}
.btn.primary{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:#052022;box-shadow:0 6px 22px rgba(33,200,160,0.06)}
.btn.ghost{background:transparent;border:1px solid rgba(255,255,255,0.06);color:#dff2ef}
.btn.large{padding:0.9rem 1.2rem;font-size:1.05rem}
.social-proof{padding:2rem 0}
.social-proof h2{color:var(--accent2)}
.testimonials{display:grid;grid-template-columns:repeat(2,1fr);gap:1rem;margin-top:1rem}
.testimonials blockquote{background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));padding:1rem;border-radius:10px;border:1px solid rgba(255,255,255,0.02);color:#dff8f6}
.testimonials cite{display:block;margin-top:0.6rem;color:var(--muted);font-size:0.9rem}
@media(max-width:880px){.testimonials{grid-template-columns:1fr}}
.benefits{padding:2rem 0}
.benefit-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:1rem;list-style:none;padding:0;margin:0}
.benefit-grid li{background:var(--glass);padding:1rem;border-radius:12px;border:1px solid rgba(255,255,255,0.02);color:#e8fbf7}
.benefit-grid h3{margin:0 0 0.4rem;color:var(--accent1)}
@media(max-width:880px){.benefit-grid{grid-template-columns:1fr}}
.process{padding:2rem 0}
.process-list{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:1rem;border-radius:10px;color:#dff8f6}
.process-list li{margin:0.6rem 0}
.faq{padding:2rem 0}
.faq dl{display:grid;gap:0.6rem;color:var(--muted)}
.faq dt{font-weight:700;color:#c8fff0}
.lead-magnet{padding:2rem 0}
.lead-form{display:flex;gap:0.6rem;max-width:40rem}
.lead-form input{flex:1;padding:0.6rem;border-radius:8px;border:1px solid rgba(255,255,255,0.06);background:transparent;color:#e9fffb}
.privacy{font-size:0.85rem;color:var(--muted);margin-top:0.6rem}
.cta-band{padding:1.2rem 0;background:linear-gradient(90deg,rgba(24,40,34,0.6),rgba(6,12,18,0.6));border-top:1px solid rgba(255,255,255,0.02)}
.cta-inner{display:flex;align-items:center;justify-content:space-between;gap:1rem}
.cta-inner h3{margin:0;color:#ddfff7}
.site-footer{padding:1.2rem 0;border-top:1px solid rgba(255,255,255,0.02);color:var(--muted)}
.footer-inner{display:flex;align-items:center;justify-content:space-between;gap:1rem}
.footer-nav a{color:var(--muted);text-decoration:none;margin-left:0.7rem}
@media(max-width:760px){.cta-inner{flex-direction:column;align-items:flex-start}.footer-inner{flex-direction:column;align-items:flex-start}}
/* subtle animations */
.hero-inner,.benefit-grid li,.testimonials blockquote{transform:translateY(0);transition:transform .6s ease,opacity .6s ease}
.loaded .hero-inner{transform:none}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Mobile nav toggle
  const navToggle = document.getElementById('navToggle');
  const nav = document.getElementById('mainNav');
  navToggle && navToggle.addEventListener('click', ()=>{
    const expanded = navToggle.getAttribute('aria-expanded') === 'true';
    navToggle.setAttribute('aria-expanded', String(!expanded));
    if(nav.style.display === 'block'){
      nav.style.display = '';
    } else {
      nav.style.display = 'block';
    }
  });

  // Smooth scroll for same-page anchors
  document.addEventListener('click', function(e){
    const a = e.target.closest('a[href^="#"]');
    if(!a) return;
    e.preventDefault();
    const id = a.getAttribute('href').slice(1);
    const el = document.getElementById(id);
    if(el) el.scrollIntoView({behavior:'smooth',block:'start'});
  });

  // Lead magnet form handling (mock)
  const leadForm = document.getElementById('leadForm');
  if(leadForm){
    leadForm.addEventListener('submit', function(e){
      e.preventDefault();
      const email = document.getElementById('leadEmail').value.trim();
      if(!email || !email.includes('@')){
        alert('Please enter a valid email to receive the guide.');
        return;
      }
      // Simulate successful signup + provide the guide link
      const guideUrl = '/assets/guide/rebalance.pdf';
      try{navigator.clipboard && navigator.clipboard.writeText(email);}catch(e){}
      leadForm.innerHTML = '<p class="sent">Thank you! Check your inbox for the guide. If you don\'t see it, check promotions or spam.</p>';
      // Fire a gentle visual acknowledgement
      const bar = document.querySelector('.cta-band');
      if(bar){bar.animate([{opacity:0.85},{opacity:1}],{duration:600})}
      console.log('Lead captured (mock):', email);
    });
  }

  // Simple load animation trigger
  window.addEventListener('load', function(){document.documentElement.classList.add('loaded')});
})();"} 
